#!/usr/bin/env bash
set -euo pipefail
TASK_KIT_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$TASK_KIT_ROOT"
: "${DOCS_PYTHON:=python3.12}"
: "${DOCS_NODE:=node}"
# The starter is generated by init, as users get it, then built and linted.
STARTER="$TASK_KIT_ROOT/.build/starter"
rm -rf "$STARTER"
mkdir -p "$STARTER"
git -C "$STARTER" init -q
"$DOCS_PYTHON" docsite.py init "$STARTER" --title "Documentation kit"
git -C "$STARTER" add -A
export DOCSITE_PROJECT_ROOT="$STARTER"
export PYTHONPATH="$TASK_KIT_ROOT/tooling"
"$DOCS_PYTHON" docsite.py build --project "$STARTER"
"$DOCS_PYTHON" docsite.py lint --project "$STARTER" --strict
"$DOCS_PYTHON" -m unittest discover -s tests -p 'test_*.py'
# The kit's own reference website, built from the repository root.
DOCSITE_PROJECT_ROOT="$TASK_KIT_ROOT" "$DOCS_PYTHON" docsite.py build --project .
DOCSITE_PROJECT_ROOT="$TASK_KIT_ROOT" "$DOCS_PYTHON" docsite.py lint --project . --strict
"$DOCS_NODE" tests/test_math_runtime.cjs
"$DOCS_NODE" tests/test_site_filelinks.cjs
# Every shared script must parse, even where no browser is available.
scripts=(theme/components/*.js tooling/*.cjs tests/*.cjs)
for script in "${scripts[@]}"; do
  "$DOCS_NODE" --check "$script"
done
echo "Syntax: ${#scripts[@]} scripts parse."
# Real-browser suites: starter reader, layout helpers, panel switcher and the
# kit's own site. They run when Playwright resolves. DOCS_REQUIRE_BROWSER=1
# makes a missing Playwright fail instead of skipping, as the Pages workflow does.
if "$DOCS_NODE" -e "require(process.env.DOCS_PLAYWRIGHT || 'playwright')" 2>/dev/null; then
  # Keep Chromium away from the desktop session.
  export DBUS_SESSION_BUS_ADDRESS="unix:path=/nonexistent-docs-kit-review"
  cap=()
  if systemd-run --user --scope --quiet -p MemoryMax=4G -p MemorySwapMax=0 true 2>/dev/null; then
    cap=(systemd-run --user --scope --quiet -p MemoryMax=4G -p MemorySwapMax=0)
  fi
  for suite in visual_review test_browser_checks test_panel_switcher own_site_review; do
    ${cap[@]+"${cap[@]}"} timeout 280 "$DOCS_NODE" "tests/$suite.cjs"
  done
elif [ "${DOCS_REQUIRE_BROWSER:-0}" = 1 ]; then
  echo "ERROR: browser suites are required, but Playwright does not resolve. Set DOCS_PLAYWRIGHT." >&2
  exit 1
else
  echo "SKIPPED: browser suites (starter reader, layout helpers, panel switcher, own site)."
  echo "         Set DOCS_PLAYWRIGHT and DOCS_CHROMIUM to run them."
fi
